import { sectionTitlePagePatch } from '@/lib/filmSectionTitlePage';
import { Settings2, Image, Palette, RotateCcw, Trash2, Upload } from 'lucide-react';
import { Popover, PopoverContent, PopoverTrigger } from './ui/popover';
import type { BookSection } from '@/lib/filmBooks';
import { useState } from 'react';
const action='flex min-h-10 w-full items-center gap-2 rounded-md px-2 py-2 text-left text-sm hover:bg-ink/5 disabled:opacity-40';
export default function FilmSectionMenu({ section, pageNumber, update, background, titleImage, importTitle, remove, canRemove, poster }: {section:BookSection;pageNumber?:number;update:(patch:Partial<BookSection>)=>void;background:()=>void;titleImage:()=>void;importTitle:(file:File|undefined)=>void;remove:()=>void;canRemove:boolean;poster:string}) {
  const [open,setOpen]=useState(false);
  return <Popover open={open} onOpenChange={setOpen}><PopoverTrigger asChild><button type="button" aria-label={pageNumber?`Options de la section · page ${pageNumber}`:'Options de la section'} title="Options de la section" className="inline-flex min-h-10 items-center gap-1.5 rounded-md border border-ink/20 bg-paper px-3 text-sm hover:bg-ink/5"><Settings2 size={16}/><span>Section</span></button></PopoverTrigger><PopoverContent collisionPadding={{top:72,bottom:88,left:12,right:12}} align="end" style={{maxHeight:"min(70vh, var(--radix-popover-content-available-height))"}} role="dialog" aria-label="Options de la section" className="max-h-[70vh] w-80 max-w-[calc(100vw-2rem)] overflow-y-auto bg-paper p-4 text-foreground">
    <h2 className="mb-3 font-semibold">Options de la section</h2>
    <label className="block text-xs font-semibold text-muted-foreground">Nom de la section<input className="mb-4 mt-1 h-10 w-full rounded-md border border-ink/25 bg-paper px-3 text-sm text-foreground" value={section.name} onChange={e=>update({name:e.target.value})}/></label>
    {section.kind!=='cover'&&<label className="mb-4 flex min-h-10 items-center justify-between gap-3 text-sm">Couleur de l’étiquette<input aria-label="Couleur de l’étiquette" type="color" className="h-10 w-14 cursor-pointer rounded border border-ink/25" value={section.labelColor??'#1da429'} onChange={e=>update({labelColor:e.target.value})}/></label>}
    <div className="mb-3 border-t border-ink/10 pt-3"><p className="mb-1 text-xs font-semibold text-muted-foreground">Fond des pages · alternance gauche / droite</p><button className={action} onClick={()=>{setOpen(false);background();}}><Palette size={16}/><span>Fond depuis les ressources</span></button>{section.background&&<button className={action} onClick={()=>update({background:'',backgroundVariants:undefined})}><RotateCcw size={16}/>Retirer le fond des pages</button>}</div>
    {!section.kind&&<div className="border-t border-ink/10 pt-3"><label className="mb-3 flex min-h-11 items-center gap-2 text-sm font-semibold"><input type="checkbox" checked={!!section.pages[0]?.titlePage} onChange={event=>update(sectionTitlePagePatch(section,event.target.checked))} />Page de titre de la section</label>{section.pages[0]?.titlePage&&<><img src={section.titleBackground||poster} alt="Fond du titre de section" className="mb-2 h-20 w-full rounded object-cover"/><button className={action} onClick={()=>{setOpen(false);titleImage();}}><Image size={16}/>Image du titre depuis les ressources</button><label className={`${action} cursor-pointer`}><Upload size={16}/>Depuis l’ordinateur<input aria-label="Importer le fond du titre de section" type="file" accept="image/png,image/jpeg,image/webp" className="hidden" onChange={e=>{importTitle(e.target.files?.[0]);e.target.value='';}}/></label>{section.titleBackground&&<button className={action} onClick={()=>update({titleBackground:''})}><RotateCcw size={16}/>Revenir à l’image du projet</button>}</>}</div>}

  </PopoverContent></Popover>;
}
